// Every dictionary is generated by the distributed HTML through its GUI state.
const fs=require('fs'),path=require('path');
const repo=path.resolve(__dirname,'..');
const {app}=require(path.join(repo,'tests/helpers.cjs'));
const root=path.resolve(process.argv[3]||'priority_validation');
const name=process.argv[2],a=app();
const patch=(name,purpose,p='0',normal='(1 0 0)')=>({name,purpose,p,normal,U:'(0 0 0)',area:'0.001',Q:'0',mdot:'0',T:'293.15',alpha:'0'});
(async()=>{try{
 if(name.startsWith('piso_')||name.startsWith('pimple_')){
  const settings={caseName:name,solver:name.startsWith('pimple_')?'pimpleFoam':'pisoFoam',includeSnappy:false,includeBlockMesh:true,meshMotion:'static',turbulenceType:name.includes('ras')?'RAS':'laminar',rasModel:'kOmegaSST',nu:'0.01',rho:'1000',initialU:'(0 0 0)',boxMin:'(0 0 0)',boxMax:'(1 0.1 0.01)',blockCells:'40 40 1',bmXMinusName:'inlet',bmXMinusType:'patch',bmXPlusName:'outlet',bmXPlusType:'patch',bmYMinusName:'bottom',bmYMinusType:'wall',bmYPlusName:'top',bmYPlusType:'wall',bmZMinusName:'frontBack',bmZMinusType:'empty',bmZPlusName:'frontBack',bmZPlusType:'empty',nProc:name.includes('parallel')?'2':'1',decompMethod:'simple',simpleN:name.includes('parallel')?'2 1 1':'1 1 1',caseRunMode:name.includes('restart')?'restart':'fresh',startFrom:'startTime',startTime:name.includes('restart')?'0.5':'0',deltaT:'0.001',adjustTimeStep:'no',endTime:name.includes('ras')?'0.05':'1',writeControl:'timeStep',writeInterval:'10',writePrecision:'12',ddtScheme:'Euler',divUScheme:'Gauss linear',nOuter:'2',nCorrectors:'3',nNonOrth:'0',pTol:'1e-10',pRelTol:'0',fieldTol:'1e-10',foResiduals:true,foCourant:true,foSurfaceFieldValue:true,foSFVMode:'auto',foBasicWriteControl:'timeStep',foBasicWriteInterval:'10',foSFVInterval:'10',foYPlus:false,foWallShear:true};
  for(const [k,v] of Object.entries(settings))a.set(k,v);
  const snap=JSON.parse(JSON.stringify(a.api.projectSnapshot()));snap.patches=[patch('inlet','pressureInlet','.1','(-1 0 0)'),patch('outlet','pressureOutlet'),patch('bottom','wallNoSlip'),patch('top','wallNoSlip'),patch('frontBack','empty')];a.api.restoreProject(snap);
 }else if(name.startsWith('amr_')||name.startsWith('csv_')||name.startsWith('gravity_')){
  const amr=name.startsWith('amr_');a.api.restoreProject(JSON.parse(fs.readFileSync(path.join(repo,'examples/interfoam',amr?'damBreak_amr.project.json':'sloshing_csv.project.json'),'utf8')));
  for(const [k,v]of Object.entries({caseName:name,caseRunMode:name.includes('restart')?'restart':'fresh',startFrom:'startTime',startTime:name.includes('restart')?(amr?'0.1':'10.25'):'0',nProc:name.includes('parallel')?'2':'1',decompMethod:'simple',simpleN:name.includes('parallel')?'2 1 1':'1 1 1',blockCells:amr?'40 2 40':'12 8 30',adjustTimeStep:'no',deltaT:amr?'0.0005':'0.01',endTime:amr?'0.2':'21',writeControl:'timeStep',writeInterval:amr?'100':'25',writePrecision:'12',foHeightInterval:amr?'0.01':'0.05',foBasicWriteInterval:'0.05',foWallSamples:!amr}))a.set(k,v);
  if(name.startsWith('gravity_')){
   a.set('endTime','50');a.set('writeInterval','100');a.set('foHeightInterval','0.1');a.set('foWallSamples',false);a.set('accelerationTail','none');
   const ax=name.includes('tilt')?0.981:0;const csv=`time,ax,ay,az\n0,${ax},0,0\n51,${ax},0,0\n`;
   await a.api.importAccelerationFile({name:name+'.csv',size:csv.length,text:async()=>csv});
  }
  if(name.includes('tight'))for(const [k,v]of Object.entries({pTol:'1e-11',pRelTol:'0',fieldTol:'1e-11'}))a.set(k,v);
  if(name.includes('interior'))a.set('foHeightLocations','(0.15 0.37 0.025)\n(0.35 0.37 0.025)\n(0.85 0.37 0.025)\n(1.05 0.37 0.025)');
 }else throw Error('Unknown case');
 a.click('generateBtn');const errors=[...a.api.blockingErrors()];if(errors.length)throw Error(errors.join('\n'));
 const dest=path.join(root,name);if(fs.existsSync(dest))throw Error('Refuse overwrite '+dest);
 for(const file of a.api.outputs()){const p=path.join(root,file.path);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,file.text)}
 fs.writeFileSync(path.join(dest,name+'.project.json'),JSON.stringify(a.api.projectSnapshot(),null,2));console.log('HTML exported '+name);
}finally{a.close()}})().catch(e=>{console.error(e);process.exitCode=1});
